parsed.api_descriptions:
API_name: get_divisions_near_location
Description:
{
  "description": "Returns a list of administrative divisions (cities, counties, islands, or regions) located within a specified radius of a given GPS coordinate. Each result includes the division's name, country, region, population, and distance from the specified location. Supports filtering by country, time zone, population range, and name prefix. Results can be displayed in multiple languages and sorted by various fields.",
  "required_parameters": [
    {
      "name": "locationId",
      "type": "STRING",
      "description": "The GPS coordinate of the center location, expressed in ISO-6709 format as latitude followed by longitude (format: ±DD.DDDD±DDD.DDDD).",
      "default": "+33.832213-118.387099"
    },
    {
      "name": "radius",
      "type": "NUMBER",
      "description": "The search radius around the specified GPS location within which to find nearby divisions.",
      "default": "100"
    }
  ],
  "optional_parameters": [
    {
      "name": "distanceUnit",
      "type": "STRING",
      "description": "The unit of distance to use for the radius. Accepted values: 'MI' (miles) or 'KM' (kilometers).",
      "default": "KM"
    },
    {
      "name": "countryIds",
      "type": "STRING",
      "description": "Restrict results to divisions within these countries only. Provide a comma-delimited list of ISO country codes or WikiData IDs (e.g., 'US,CA')."
    },
    {
      "name": "excludedCountryIds",
      "type": "STRING",
      "description": "Exclude divisions belonging to these countries from the results. Provide a comma-delimited list of ISO country codes or WikiData IDs."
    },
    {
      "name": "timeZoneIds",
      "type": "STRING",
      "description": "Restrict results to divisions located within these time zones only. Provide a comma-delimited list of time-zone IDs (e.g., 'America/New_York,Europe/London')."
    },
    {
      "name": "minPopulation",
      "type": "NUMBER",
      "description": "Only include divisions with a population greater than or equal to this value.",
      "default": "0"
    },
    {
      "name": "maxPopulation",
      "type": "NUMBER",
      "description": "Only include divisions with a population less than or equal to this value.",
      "default": "0"
    },
    {
      "name": "namePrefix",
      "type": "STRING",
      "description": "Only return divisions whose names start with this prefix. If 'languageCode' is also set, the prefix is matched against the name in that language."
    },
    {
      "name": "namePrefixDefaultLangResults",
      "type": "BOOLEAN",
      "description": "When performing name-prefix matching with a non-default language set, whether to also match against names in the default language."
    },
    {
      "name": "languageCode",
      "type": "STRING",
      "description": "Return results with place names displayed in this language (e.g., 'en', 'de', 'fr', 'ru')."
    },
    {
      "name": "asciiMode",
      "type": "BOOLEAN",
      "description": "If true, display results using ASCII characters only, removing diacritics and special characters."
    },
    {
      "name": "hateoasMode",
      "type": "BOOLEAN",
      "description": "If true, include HATEOAS-style pagination links in the response."
    },
    {
      "name": "includeDeleted",
      "type": "STRING",
      "description": "Whether to include divisions that have been marked as deleted. Accepted values: 'ALL', 'SINCE_YESTERDAY', 'SINCE_LAST_WEEK', 'NONE'.",
      "default": "NONE"
    },
    {
      "name": "limit",
      "type": "NUMBER",
      "description": "The maximum number of division results to return per request.",
      "default": "10"
    },
    {
      "name": "offset",
      "type": "NUMBER",
      "description": "The zero-based offset into the result set, used for pagination.",
      "default": "0"
    },
    {
      "name": "sort",
      "type": "STRING",
      "description": "Specify how to sort the results. Format: '±SORT_FIELD,±SORT_FIELD' where '+' means ascending and '-' means descending. SORT_FIELD options: 'countryCode', 'elevation', 'name', 'population'. Example: '-population,+name'."
    }
  ]
}

