parsed.api_descriptions:
API_name: get_hotels_by_location
Description:
{
  "description": "Search for hotels within a geographic bounding box using GPS coordinates and travel dates. Returns hotel listings with pricing, ratings, and availability, replicating TripAdvisor's hotel search feature.",
  "required_parameters": [
    {
      "name": "bl_latitude",
      "type": "Number",
      "description": "Bottom-left (southwest) latitude of the bounding box search area.",
      "default": "11.847676"
    },
    {
      "name": "tr_latitude",
      "type": "Number",
      "description": "Top-right (northeast) latitude of the bounding box search area.",
      "default": "12.838442"
    },
    {
      "name": "bl_longitude",
      "type": "Number",
      "description": "Bottom-left (southwest) longitude of the bounding box search area.",
      "default": "108.587349"
    },
    {
      "name": "tr_longitude",
      "type": "Number",
      "description": "Top-right (northeast) longitude of the bounding box search area.",
      "default": "109.471078"
    },
    {
      "name": "checkin",
      "type": "String",
      "description": "Check-in date in 'YYYY-MM-DD' format.",
      "default": "2025-08-01"
    },
    {
      "name": "checkout",
      "type": "String",
      "description": "Check-out date in 'YYYY-MM-DD' format.",
      "default": "2025-08-05"
    }
  ],
  "optional_parameters": [
    {
      "name": "adults",
      "type": "Number",
      "description": "Number of adult guests. Default is 2.",
      "default": "2"
    },
    {
      "name": "rooms",
      "type": "Number",
      "description": "Number of rooms required. Default is 1.",
      "default": "1"
    },
    {
      "name": "limit",
      "type": "Number",
      "description": "Maximum number of hotel results to return per request.",
      "default": "30"
    },
    {
      "name": "currency",
      "type": "String",
      "description": "Currency code for price display (e.g., 'USD', 'EUR', 'TWD').",
      "default": "USD"
    },
    {
      "name": "offset",
      "type": "Number",
      "description": "Pagination offset for retrieving subsequent pages of results.",
      "default": "0"
    },
    {
      "name": "lang",
      "type": "String",
      "description": "Language/locale code for the response (e.g., 'en_US', 'zh_TW', 'ja_JP').",
      "default": "en_US"
    }
  ]
}

