API_name: get_restaurants_by_location
Description:
{
  "description": "Search for restaurants within a geographic bounding box using GPS coordinates. Returns restaurant listings including name, cuisine, rating, and contact information, replicating TripAdvisor's restaurant search.",
  "required_parameters": [
    {
      "name": "bl_latitude",
      "type": "Number",
      "description": "Bottom-left (southwest) latitude of the bounding box search area.",
      "default": "11.847676"
    },
    {
      "name": "tr_latitude",
      "type": "Number",
      "description": "Top-right (northeast) latitude of the bounding box search area.",
      "default": "12.838442"
    },
    {
      "name": "bl_longitude",
      "type": "Number",
      "description": "Bottom-left (southwest) longitude of the bounding box search area.",
      "default": "108.587349"
    },
    {
      "name": "tr_longitude",
      "type": "Number",
      "description": "Top-right (northeast) longitude of the bounding box search area.",
      "default": "109.471078"
    }
  ],
  "optional_parameters": [
    {
      "name": "limit",
      "type": "Number",
      "description": "Maximum number of restaurant results to return per request.",
      "default": "30"
    },
    {
      "name": "currency",
      "type": "String",
      "description": "Currency code for price display (e.g., 'USD', 'EUR', 'TWD').",
      "default": "USD"
    },
    {
      "name": "offset",
      "type": "Number",
      "description": "Pagination offset for retrieving subsequent pages of results.",
      "default": "0"
    },
    {
      "name": "lang",
      "type": "String",
      "description": "Language/locale code for the response (e.g., 'en_US', 'zh_TW', 'ja_JP').",
      "default": "en_US"
    }
  ]
}

API_name: calculate_mortgage_payment
Description:
{
  "description": "Provides detailed mortgage and other home financing payment information. It uses the standard mortgage calculation formulas to calculate interest and monthly/annual payments.",
  "required_parameters": [
    {
      "name": "interest_rate",
      "type": "Number",
      "description": "Annual interest rate (in %). For example, a 3.5% interest rate would be 3.5. Cannot exceed 10000."
    }
  ],
  "optional_parameters": [
    {
      "name": "loan_amount",
      "type": "Number",
      "description": "Principal loan amount.",
      "default": "200000"
    },
    {
      "name": "home_value",
      "type": "Number",
      "description": "Total value of the home or asset. Must be greater than downpayment.",
      "default": "0"
    },
    {
      "name": "downpayment",
      "type": "Number",
      "description": "Downpayment on the home or asset. Cannot exceed home_value.",
      "default": "0"
    },
    {
      "name": "duration_years",
      "type": "Number",
      "description": "Duration of the loan in years. Must be between 1 and 10000. If not set, default value is 30 years.",
      "default": "30"
    },
    {
      "name": "monthly_hoa",
      "type": "Number",
      "description": "Monthly homeowner association fees.",
      "default": "0"
    },
    {
      "name": "annual_property_tax",
      "type": "String",
      "description": "Annual property tax owed."
    },
    {
      "name": "annual_home_insurance",
      "type": "Number",
      "description": "Annual homeowner's insurance bill.",
      "default": "0"
    }
  ]
}

